if __name__=='__main__':
    dst=ROOT/'references';dst.mkdir(exist_ok=True)
    (dst/'catalog.json').write_text(json.dumps(R,ensure_ascii=False,indent=2),encoding='utf8')
    for prefix,name in [('D','深度学习'),('F','特征挖掘'),('C','融合研究')]:
        rows=[r for r in R if r['id'].startswith(prefix)]
        with (dst/f'{name}_参考文献.csv').open('w',encoding='utf-8-sig',newline='') as f:
            w=csv.DictWriter(f,fieldnames=list(R[0]));w.writeheader();w.writerows(rows)
    print('catalog entries',len(R))
